 static List<Dictionary<string,object>> Addresses(){var result=new List<Dictionary<string,object>>();foreach(var nic in NetworkInterface.GetAllNetworkInterfaces()){if(nic.OperationalStatus!=OperationalStatus.Up||nic.NetworkInterfaceType==NetworkInterfaceType.Loopback||nic.NetworkInterfaceType==NetworkInterfaceType.Tunnel||nic.Name.ToLowerInvariant().Contains("tun"))continue;foreach(var a in nic.GetIPProperties().UnicastAddresses){if(a.Address.AddressFamily==AddressFamily.InterNetwork&&Private(a.Address)&&!IPAddress.IsLoopback(a.Address))result.Add(Obj("ip",a.Address.ToString(),"adapter",nic.Name,"url","https://"+a.Address+":"+Port+"/"));}}return result;}
