 static X509Certificate2 MakeCertificate(){Directory.CreateDirectory(Folder);var ips=Addresses().Select(a=>(string)a["ip"]).OrderBy(x=>x).ToArray();string stamp=String.Join(",",ips),file=Path.Combine(Folder,"certificate.bin"),stampFile=Path.Combine(Folder,"certificate-addresses.txt");if(File.Exists(file)&&File.Exists(stampFile)&&File.ReadAllText(stampFile)==stamp){try{var existing=new X509Certificate2(ProtectedData.Unprotect(File.ReadAllBytes(file),null,DataProtectionScope.CurrentUser),"",X509KeyStorageFlags.UserKeySet|X509KeyStorageFlags.Exportable);if(existing.NotAfter>DateTime.Now.AddDays(7))return existing;}catch{}}
