 static void Start(bool lan,int port){if(port<1024||port>65535)throw new ArgumentException("端口需为 1024–65535");if(Listener!=null)Listener.Stop();Listener=null;Lan=lan;Port=port;Certificate=MakeCertificate();var listener=new TcpListener(lan?IPAddress.Any:IPAddress.Loopback,port);listener.Start(16);Listener=listener;Error="";Rotate();if(lan)FirewallRule();Task.Run(async()=>{while(Alive&&Listener==listener){try{var client=await listener.AcceptTcpClientAsync();if(!Slots.Wait(0)){client.Close();continue;}Task.Run(()=>{try{Serve(client);}finally{client.Close();Slots.Release();}});}catch{break;}}});}
