 static Dictionary<string,object> Control(Dictionary<string,object> req){var body=req.ContainsKey("body")?(Dictionary<string,object>)req["body"]:Obj();lock(Sync){switch(S(req,"op")){case "start":Start(B(body,"lan"),body.ContainsKey("port")?Convert.ToInt32(body["port"]):43827);break;case "stop":if(Listener!=null)Listener.Stop();Listener=null;Requests.Clear();Pin="";break;case "rotate":Rotate();break;case "approve":{Pending p;if(!Requests.TryGetValue(S(body,"id"),out p)||p.status!="pending"||p.expires<Now())throw new ArgumentException("配对请求已失效");if(Devices.Count>=16)throw new ArgumentException("最多授权 16 个设备");string token=Secret();var d=new Device {id=p.id,name=p.name,hash=Hash(token),ip=p.ip,created=Now(),expires=Now()+30*86400,control=B(body,"control")};Devices[d.id]=d;p.token=token;p.control=d.control;p.status="approved";Save();Rotate();break;}case "reject":{Pending p;if(Requests.TryGetValue(S(body,"id"),out p))p.status="rejected";break;}case "revoke":Devices.Remove(S(body,"id"));Requests.Remove(S(body,"id"));Save();break;case "permission":{Device d;if(!Devices.TryGetValue(S(body,"id"),out d))throw new ArgumentException("设备不存在");d.control=B(body,"control");Save();break;}case "state":break;case "quit":Alive=false;if(Listener!=null)Listener.Stop();Listener=null;break;default:throw new ArgumentException("不支持的本地手机服务操作");}return Obj("ok",true,"data",State());}}
