 static Device Authenticate(Dictionary<string,string> headers,string ip){string token="",authorization;if(headers.TryGetValue("authorization",out authorization)&&authorization.StartsWith("Bearer ",StringComparison.Ordinal))token=authorization.Substring(7);else{string cookie;if(headers.TryGetValue("cookie",out cookie))foreach(string part in cookie.Split(';')){var p=part.Trim();if(p.StartsWith("hhub=",StringComparison.Ordinal))token=p.Substring(5);}}if(token.Length<32||token.Length>128)return null;string hash=Hash(token);lock(Sync){foreach(var d in Devices.Values)if(d.expires>Now()&&Equal(d.hash,hash)){d.seen=Now();d.ip=ip;return new Device {id=d.id,name=d.name,control=d.control};}}return null;}
 static void Response(SslStream stream,int status,string mime,byte[] content,string cookie=""){string reason=status==200?"OK":status==202?"Accepted":status==401?"Unauthorized":status==403?"Forbidden":status==429?"Too Many Requests":"Bad Request";string head="HTTP/1.1 "+status+" "+reason+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+content.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\n"+(cookie.Length>0?"Set-Cookie: hhub="+cookie+"; Path=/; Max-Age=2592000; HttpOnly; Secure; SameSite=Strict\r\n":"")+"\r\n";byte[] header=Encoding.ASCII.GetBytes(head);stream.Write(header,0,header.Length);stream.Write(content,0,content.Length);stream.Flush();}
