 static void Serve(TcpClient client){client.ReceiveTimeout=4000;client.SendTimeout=4000;var peer=(IPEndPoint)client.Client.RemoteEndPoint;if(!Private(peer.Address))return;using(var ssl=new SslStream(client.GetStream(),false)){ssl.ReadTimeout=4000;ssl.WriteTimeout=4000;try{ssl.AuthenticateAsServer(Certificate,false,SslProtocols.Tls12,false);var raw=new List<byte>();while(raw.Count<8192){int b=ssl.ReadByte();if(b<0)throw new IOException();raw.Add((byte)b);int n=raw.Count;if(n>=4&&raw[n-4]==13&&raw[n-3]==10&&raw[n-2]==13&&raw[n-1]==10)break;}if(raw.Count>=8192)throw new IOException();string[] lines=Encoding.ASCII.GetString(raw.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);var first=lines[0].Split(' ');if(first.Length!=3||first[2]!="HTTP/1.1")throw new IOException();string method=first[0],path=first[1].Split('?')[0];var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var line in lines.Skip(1)){int colon=line.IndexOf(':');if(colon>0){string key=line.Substring(0,colon).Trim().ToLowerInvariant();if(headers.ContainsKey(key))throw new IOException();headers[key]=line.Substring(colon+1).Trim();}}string host;if(!headers.TryGetValue("host",out host))throw new IOException();Uri origin;if(!Uri.TryCreate("https://"+host,UriKind.Absolute,out origin))throw new IOException();IPAddress hostIp;if(origin.Host!="localhost"&&(!IPAddress.TryParse(origin.Host,out hostIp)||!Private(hostIp)))throw new IOException();string supplied;if(headers.TryGetValue("origin",out supplied)&&supplied!=origin.GetLeftPart(UriPartial.Authority)){Reply(ssl,403,Obj("error","不允许跨站请求"));return;}if(headers.ContainsKey("transfer-encoding"))throw new IOException();int length=0;string contentLength;if(headers.TryGetValue("content-length",out contentLength)&&(!Int32.TryParse(contentLength,out length)||length<0||length>16384))throw new IOException();var body=length>0?Json.DeserializeObject(Encoding.UTF8.GetString(ReadExact(ssl,length))) as Dictionary<string,object>:Obj();if(body=