 if(method=="POST"&&path=="/api/pair"){lock(Sync){string ip=peer.Address.ToString();Rate rate;if(!Rates.TryGetValue(ip,out rate)||Now()-rate.start>60)Rates[ip]=rate=new Rate {start=Now()};if(++rate.count>5||Rates.Count>256){Reply(ssl,429,Obj("error","配对尝试过多，请一分钟后再试"));return;}if(Pin.Length==0||PinExpires<Now()||!Equal(S(body,"code"),Pin)){Reply(ssl,403,Obj("error","配对码不正确或已过期"));return;}string name=S(body,"name","我的手机").Trim();if(name.Length==0||name.Length>64||Requests.Count>=32){Reply(ssl,400,Obj("error","名称或请求数无效"));return;}var pending=new Pending {id=Guid.NewGuid().ToString("N"),name=name,ip=ip,secret=Secret(),expires=Now()+180};Requests[pending.id]=pending;Pin="";PinExpires=0;Reply(ssl,202,Obj("id",pending.id,"pollSecret",pending.secret,"status","pending"));return;}}
